import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第十章 期间计算","description":"","frontmatter":{"title":"第十章 期间计算","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/dishizhang：qijianjisuan.md","filePath":"blogs/CC/第十章：期间计算.md"}'),o={name:"blogs/CC/dishizhang：qijianjisuan.md"};function n(s,a,l,h,d,_){return t(),r("div",null,[...a[0]||(a[0]=[i('<h3 id="第二百条" tabindex="-1">第二百条 <a class="header-anchor" href="#第二百条" aria-label="Permalink to &quot;第二百条&quot;">​</a></h3><p>民法所称的期间按照公历年、月、日、小时计算。</p><h3 id="第二百零一条" tabindex="-1">第二百零一条 <a class="header-anchor" href="#第二百零一条" aria-label="Permalink to &quot;第二百零一条&quot;">​</a></h3><p>按照年、月、日计算期间的，开始的当日不计入，自下一日开始计算。 按照小时计算期间的，自法律规定或者当事人约定的时间开始计算。</p><h3 id="第二百零二条" tabindex="-1">第二百零二条 <a class="header-anchor" href="#第二百零二条" aria-label="Permalink to &quot;第二百零二条&quot;">​</a></h3><p>按照年、月计算期间的，到期月的对应日为期间的最后一日；没有对应日的，月末日为期间的最后一日。</p><h3 id="第二百零三条" tabindex="-1">第二百零三条 <a class="header-anchor" href="#第二百零三条" aria-label="Permalink to &quot;第二百零三条&quot;">​</a></h3><p>期间的最后一日是法定休假日的，以法定休假日结束的次日为期间的最后一日。 期间的最后一日的截止时间为二十四时；有业务时间的，停止业务活动的时间为截止时间。</p><h3 id="第二百零四条" tabindex="-1">第二百零四条 <a class="header-anchor" href="#第二百零四条" aria-label="Permalink to &quot;第二百零四条&quot;">​</a></h3><p>期间的计算方法依照本法的规定，但是法律另有规定或者当事人另有约定的除外。</p>',10)])])}const u=e(o,[["render",n]]);export{p as __pageData,u as default};
